const fs = require('node:fs');
const { execFileSync } = require('node:child_process');
const file = 'docs/build/production/ledger.json';
const intended = JSON.parse(fs.readFileSync(file, 'utf8'));
let original = execFileSync('git', ['show', `HEAD:${file}`], {encoding: 'utf8'});
const rows = intended.requirements.filter(r => /^PROD-(MAN|MIX|OPS|REL)-/.test(r.id));
for (const r of rows) {
  const id = original.indexOf(`"id": "${r.id}"`);
  if (id < 0) throw new Error('Requirement missing');
  const start = original.indexOf('"implementationStatus": ', id);
  const end = original.indexOf('\n', start);
  const before = original.slice(start, end);
  const ending = before.endsWith('\r') ? '\r' : '';
  const replacement = `"implementationStatus": "implementation_complete_verification_pending",${ending}\n      "implementationNote": ${JSON.stringify(r.implementationNote)},${ending}`;
  original = original.slice(0, start) + replacement + original.slice(end);
}
if (JSON.stringify(JSON.parse(original)) !== JSON.stringify(intended)) {
  // Compare semantically without treating inserted object key order as a change.
  const canonical = v => v && typeof v === 'object' ? Array.isArray(v) ? v.map(canonical) : Object.fromEntries(Object.entries(v).sort().map(([k,w]) => [k,canonical(w)])) : v;
  if (JSON.stringify(canonical(JSON.parse(original))) !== JSON.stringify(canonical(intended))) throw new Error('Unexpected ledger change');
}
fs.writeFileSync(file, original);
console.log('Preserved original ledger formatting and all unrelated fields; only 27 status/note pairs changed');
