  const lines=buf.subarray(0,length).toString('utf8').split('\n');
  if (lines.some(line=>{try {const j=JSON.parse(line);return j.type==='turn_context' && j.payload?.cwd?.replaceAll('\\','/').toLowerCase().endsWith('/prod6-l3-live-managed');}catch{return false;}})) {matched=file.full;break;}
}
if (!matched) {console.log('Own command log not located; use verification report command table');process.exit(0);}
const commands=[];
for (const line of fs.readFileSync(matched,'utf8').split('\n')) {
  let j;try{j=JSON.parse(line);}catch{continue;}
